#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a string stream to hold the HTML output
    std::stringstream htmlStream;

    // Write the markdown text to the string stream
    htmlStream << markdown;

    // Return the HTML string from the string stream
    return htmlStream.str();
}

int main() {
    // Example usage
    std::string markdown = "# My Heading\n\nThis is a paragraph.\n\n* This is a list item\n* This is another list item\n\n";
    std::string html = markdownToHtml(markdown);

    // Print the HTML output
    std::cout << html << std::endl;

    return 0;
}
```

